import { useEffect, useEffectEvent, useState } from "react";
import { Button } from "../../ui/Button";
import { Card } from "../../ui/Card";
import { CodeBlock } from "../../ui/CodeBlock";
import { InfoRow } from "../../ui/InfoRow";
import { Notice } from "../../ui/Notice";
import { TextField } from "../../ui/TextField";
import { describeError } from "../describeError";
import { hmacSha256Async, type Sealed, sealAsync, sha256Async } from "./crypto.lucent";
import { KnownAnswerRow } from "./KnownAnswerRow";
import { knownAnswers } from "./knownAnswers";

interface Output {
  sha256: string;
  hmac: string;
  sealed: Sealed;
}

async function compute(message: string, key: string): Promise<Output> {
  return {
    sha256: await sha256Async(message),
    hmac: await hmacSha256Async(key, message),
    sealed: await sealAsync(message),
  };
}

export function CryptoDemo() {
  const [message, setMessage] = useState("Hello from Lucent");
  const [key, setKey] = useState("a shared secret");
  const [output, setOutput] = useState<{ input: string; result: Output } | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function run() {
    try {
      setOutput({ input: message, result: await compute(message, key) });
      setError(null);
    } catch (e) {
      setError(describeError(e));
    }
  }

  const runOnMount = useEffectEvent(run);

  useEffect(() => {
    void runOnMount();
  }, []);

  const result = output?.result;

  return (
    <>
      <Card title="Input">
        <TextField
          testID="crypto-message"
          label="Message"
          value={message}
          onChangeText={setMessage}
        />
        <TextField testID="crypto-key" label="HMAC key" value={key} onChangeText={setKey} />
        <Button testID="crypto-run" label="Hash, sign and encrypt" onPress={() => void run()} />
      </Card>

      {error ? <Notice tone="danger" title="Crypto failed" message={error} /> : null}

      {result ? (
        <>
          <Card title="SHA-256">
            <CodeBlock testID="crypto-sha256" text={result.sha256} />
          </Card>

          <Card title="HMAC-SHA256">
            <CodeBlock testID="crypto-hmac" text={result.hmac} />
          </Card>

          <Card title="AES-256-GCM, with a new key">
            <InfoRow code label="Key" value={result.sealed.key} />
            <InfoRow code label="Nonce" value={result.sealed.nonce} />
            <InfoRow code label="Ciphertext and tag" value={result.sealed.ciphertext} />

            <Notice
              testID="crypto-roundtrip"
              tone={result.sealed.opened === output.input ? "success" : "danger"}
              title={
                result.sealed.opened === output.input
                  ? "Decrypts back to the message"
                  : "Decrypted text differs"
              }
              message={result.sealed.opened}
            />
          </Card>
        </>
      ) : null}

      <Card title="Known answers">
        {knownAnswers.map((answer) => (
          <KnownAnswerRow key={answer.name} answer={answer} />
        ))}
      </Card>
    </>
  );
}
